import * as functions from 'firebase-functions/v1'
import puppeteer, { Browser } from 'puppeteer-core'
import chromium from '@sparticuz/chromium-min'
import { deleteStudyFiles } from './studyFiles'

const admin = require('firebase-admin')
const cors = require('cors')({ origin: true })

const runtimeOpts: functions.RuntimeOptions = {
  memory: '1GB',
  timeoutSeconds: 60,
  // Each request starts its own Chromium: bound what a flood of requests can cost.
  maxInstances: 5,
}

// Study ids are generated by the app (a UUID, sometimes prefixed with `study-`).
const STUDY_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/

const bucket = admin.storage().bucket('bible-strong-app.appspot.com')

// Prints the public page of the study. Returns null when the site has no such page.
const renderStudyPDF = async (studyId: string): Promise<Uint8Array | null> => {
  let browser: Browser

  if (process.env.IS_OFFLINE) {
    browser = await puppeteer.launch({
      args: ['--no-sandbox', '--disable-setuid-sandbox'],
      executablePath: '/opt/homebrew/bin/chromium',
    })
  } else {
    browser = await puppeteer.launch({
      args: [
        ...chromium.args,
        '--hide-scrollbars',
        '--disable-web-security',
      ],
      defaultViewport: { width: 1920, height: 1080 },
      executablePath: await chromium.executablePath(
        'https://github.com/Sparticuz/chromium/releases/download/v131.0.0/chromium-v131.0.0-pack.tar'
      ),
      headless: true,
    })
  }

  // Close Chromium before answering: work after the response is not guaranteed to run.
  try {
    const page = await browser.newPage()

    const result = await page.goto(
      `https://bible-strong.app/studies/${studyId}`,
      {
        waitUntil: 'networkidle0',
      }
    )

    if (result?.status() === 404) return null
    if (!result?.ok()) throw new Error(`Study page answered ${result?.status()}`)

    return await page.pdf({ format: 'A4' })
  } finally {
    await browser.close()
  }
}

// Public on purpose: the app versions in the stores call it without an ID token.
export const exportStudyPDF = functions
  .runWith(runtimeOpts)
  .https.onRequest((req, res) => {
    cors(req, res, async () => {
      try {
        if (req.method !== 'POST') {
          res.status(405).send('Method not allowed')
          return
        }

        const studyId = req.body?.studyId
        if (typeof studyId !== 'string' || !STUDY_ID_PATTERN.test(studyId)) {
          res.status(400).send('Missing studyId')
          return
        }

        // Only a published study has a page to print: check before paying for Chromium.
        const study = await admin.firestore().collection('studies').doc(studyId).get()
        if (!study.exists || study.data()?.published !== true) {
          res.status(404).send('Not found')
          return
        }

        console.log('---start')
        const buffer = await renderStudyPDF(studyId)
        if (!buffer) {
          res.status(404).send('Not found')
          return
        }
        console.log('---end')

        res.setHeader('Content-Type', 'application/pdf')
        res.setHeader('Content-Disposition', 'attachment; filename="study.pdf"')
        res.end(buffer)
      } catch (error) {
        console.log('---failure')
        console.log(error)
        res.status(500).send('PDF export failed')
      }
    })
  })

export const onStudyUpdate = functions.firestore
  .document('studies/{studyId}')
  .onUpdate(async (change, context) => {
    const newValue = change.after.data()
    const previousValue = change.before.data()

    if (newValue.published !== previousValue.published || newValue.published) {
      if (!newValue.published) {
        try {
          const { id } = newValue
          await bucket.file(`images/studies/${id}.jpg`).delete()
          await bucket.file(`images/studies/${id}-whatsapp.jpg`).delete()
          console.log(`Files deleted for ${id}`)
        } catch (e) {
          console.log(e)
        }
      }
    }
  })

export const deleteStudy = functions
  .runWith({ failurePolicy: true })
  .firestore
  .document('studies/{studyId}')
  .onDelete(async (snap) => {
    await deleteStudyFiles(snap.id)
  })
